function decodeHtml(value) {
  const named = { amp: '&', apos: "'", gt: '>', lt: '<', nbsp: ' ', quot: '"' };
  return String(value).replace(/&(#x[0-9a-f]+|#\d+|[a-z]+);/gi, (match, entity) => {
    const key = entity.toLowerCase();
    if (key.startsWith('#x')) return String.fromCodePoint(Number.parseInt(key.slice(2), 16));
    if (key.startsWith('#')) return String.fromCodePoint(Number.parseInt(key.slice(1), 10));
    return named[key] ?? match;
  });
}

function textFromHtml(value) {
  return decodeHtml(String(value).replace(/<[^>]+>/g, ' ').replace(/\s+/g, ' ').trim());
}

function valueInTile(tile, pattern) {
  return tile.match(pattern)?.[1] ?? '';
}

const html = String($json.data ?? $json.body ?? '');
if (!html.includes('data-js-product-grid')) {
  throw new Error('PUMA catalogue response did not include the product grid.');
}

const seen = new Set();
const products = [];
for (const tile of html.split(/(?=<div class=\"grid-tile\")/).slice(1)) {
  const masterId = valueInTile(tile, /\bdata-masterpid=\"([^\"]+)\"/i).trim();
  const productUrlPath = decodeHtml(valueInTile(tile, /<a\s+class='product-tile-image-link[^>]*\bhref='([^']+)'/i)).trim();
  const title = textFromHtml(valueInTile(tile, /<span\s+itemprop='name'>([\s\S]*?)<\/span>/i));
  const price = valueInTile(tile, /<span\s+itemprop=\"price\"\s+content=\"([^\"]+)\"/i).trim();
  const imageUrl = valueInTile(tile, /<meta\s+name\s+itemprop=\"image\"\s+content=\"([^\"]+)\"/i).trim();
  if (!masterId || !productUrlPath || !title || !price || !imageUrl) continue;

  const productUrl = new URL(productUrlPath, 'https://au.puma.com').toString();
  const color = new URL(productUrl).searchParams.get(`dwvar_${masterId}_color`) ?? '';
  const productId = `${masterId}_${color}`;
  if (!color || seen.has(productId)) continue;
  if (!/^https:\/\/images\.puma\.com\//i.test(imageUrl)) {
    throw new Error(`PUMA product ${productId} did not provide an approved product image.`);
  }

  seen.add(productId);
  products.push({
    json: {
      product_id: productId,
      title,
      price: `A$${Number(price).toFixed(2)} AUD`,
      product_url: productUrl,
      image_url: imageUrl,
      first_seen_at: new Date().toISOString(),
    },
  });
}

if (products.length === 0) throw new Error('PUMA catalogue parsing found no products.');
return products;

function compact(value, maxLength) {
  const text = String(value).replace(/\s+/g, ' ').trim();
  return text.length <= maxLength ? text : `${text.slice(0, maxLength - 1).trimEnd()}…`;
}

function escapeMarkdown(value) { return String(value).replace(/([\\`*_{}[\]<>])/g, '\\$1'); }

function requestIdFor(value) {
  let hash = 5381;
  for (const character of value) hash = ((hash << 5) + hash) ^ character.charCodeAt(0);
  return `puma-mclaren-product-${(hash >>> 0).toString(36)}`;
}

const product = $('Only new PUMA McLaren products').item.json;
const html = String($json.data ?? $json.body ?? '');
let structuredProduct;
for (const match of html.matchAll(/<script[^>]+type=["']application\/ld\+json["'][^>]*>([\s\S]*?)<\/script>/gi)) {
  try {
    const candidate = JSON.parse(match[1].trim());
    if (candidate?.['@type'] === 'Product') { structuredProduct = candidate; break; }
  } catch {}
}

const description = compact(structuredProduct?.description ?? '', 700);
if (!description) throw new Error(`PUMA product page did not provide a description for ${product.product_id}.`);

return {
  json: {
    ...product,
    description,
    message: [
      '🧡 **New PUMA McLaren Racing product**',
      '',
      `**${escapeMarkdown(product.title)}**`,
      `**Price:** ${escapeMarkdown(product.price)}`,
      '',
      escapeMarkdown(description),
      '',
      `[View product on PUMA](${product.product_url})`,
    ].join('\n'),
    image_alt: `${product.title} product image`,
    matrix_request_id: requestIdFor(product.product_id),
  },
};
